create table public.field_interviews (code text primary key, payload jsonb not null, collected_on date not null default '2026-10-13', origin text not null default 'real' check(origin='real'));
alter table public.field_interviews enable row level security;
revoke all on public.field_interviews from anon, authenticated;
grant select on public.field_interviews to authenticated;
create policy field_anonymous_read on public.field_interviews for select to authenticated using(exists(select 1 from public.memberships m where m.user_id=(select auth.uid()) and m.role='coordinator' and m.active));
comment on table public.field_interviews is 'Anonymous academic field declarations only. No stall identifiers, photos, contacts or operational orders.';
